 "zinnia": {"niveau":"aucune","resume":"Sans danger pour les chats, les chiens et les chevaux selon l'ASPCA.","animaux":{"chats":"non","chiens":"non","autres":"Non toxique pour les chevaux (ASPCA)."},"humains":{"enfants":"inconnu","adultes":"inconnu","texte":"Fleur décorative, pas faite pour être mangée."},"parties":[],"substances":["Aucune substance toxique."],"pourquoi":"Cette plante n'est pas connue pour être toxique.","symptomes":["Rien de spécial."],"que_faire":["Si quelqu'un a mange beaucoup de cette plante et se sent mal, rincer la bouche et boire un peu d'eau.","En cas de doute ou de signes qui durent : appeler un centre antipoison (numéro de votre région) ou le 15. Si la personne va mal : 15 ou 112.","Pour un animal malade : appeler un vétérinaire.","Garder un morceau de la plante ou une photo."],"precautions":["Ne pas faire manger les fleurs aux enfants."],"precision":"L'ASPCA liste le genre Zinnia sans préciser l'espèce. Pour les personnes, aucune source ouverte ici.","verifie":true,"sources":[{"titre":"ASPCA - Zinnia","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/zinnia"}]},
 "violette-odorante": {"niveau":"faible","resume":"Les fleurs se mangent en décoration. Pour les animaux, la plante n'est pas confirmée sans danger. Les racines et les graines sont à éviter.","animaux":{"chats":"inconnu","chiens":"inconnu","autres":""},"humains":{"enfants":"non","adultes":"non","texte":"Les fleurs se mangent en petite quantité. Ne pas manger les racines ni les graines."},"parties":["racines","graines"],"substances":["Saponines (par prudence, non verifie ici) : des substances qui moussent et irritent le ventre."],"pourquoi":"Les racines et les graines de certaines violettes contiennent des substances de défense qui irritent le ventre. Pour la violette odorante, aucune source ouverte ici ne le confirmé.","symptomes":["Mal de ventre","Vomissements"],"que_faire":["Si quelqu'un a mange beaucoup de cette plante et se sent mal, rincer la bouche et boire un peu d'eau.","En cas de doute ou de signes qui durent : appeler un centre antipoison (numéro de votre région) ou le 15. Si la personne va mal : 15 ou 112.","Pour un animal malade : appeler un vétérinaire.","Garder un morceau de la plante ou une photo."],"precautions":["Ne manger que les fleurs, jamais les racines ni les graines."],"precision":"Pas de toxicité connue mais non confirmée : par prudence, ne pas la laisser manger. La violette odorante n'est pas dans la liste ASPCA ouverte (les violettes d'intérieur, autres plantes, y sont).","verifie":false,"sources":[{"titre":"ASPCA - Liste des plantes toxiques pour les chiens","url":"https://www.aspca.org/pet-care/animal-poison-control/dogs-plant-list"},{"titre":"ASPCA - Liste des plantes toxiques pour les chats","url":"https://www.aspca.org/pet-care/animal-poison-control/cats-plant-list"}]},
 "alysse-maritime": {"niveau":"aucune","resume":"Sans danger pour les chats, les chiens et les chevaux selon l'ASPCA (alysson).","animaux":{"chats":"non","chiens":"non","autres":"Non toxique pour les chevaux (ASPCA)."},"humains":{"enfants":"inconnu","adultes":"inconnu","texte":"Petite fleur décorative. Pas faite pour être mangée."},"parties":[],"substances":["Aucune substance toxique."],"pourquoi":"Cette plante n'est pas connue pour être toxique.","symptomes":["Rien de spécial."],"que_faire":["Si quelqu'un a mange beaucoup de cette plante et se sent mal, rincer la bouche et boire un peu d'eau.","En cas de doute ou de signes qui durent : appeler un centre antipoison (numéro de votre région) ou le 15. Si la personne va mal : 15 ou 112.","Pour un animal malade : appeler un vétérinaire.","Garder un morceau de la plante ou une photo."],"precautions":["Ne pas faire manger la plante aux enfants."],"precision":"L'ASPCA liste Alyssum sans préciser l'espèce ; l'alysse maritime (Lobularia maritima) est la plante de jardin courante appelée ainsi. Pour les personnes, aucune source ouverte ici.","verifie":true,"sources":[{"titre":"ASPCA - Alysson","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/alyssum"}]},
 "celeri-branche": {"niveau":"faible","resume":"Se mange en légume. Pour les animaux, la plante n'est pas confirmée sans danger par une liste ouverte ici.","animaux":{"chats":"inconnu","chiens":"inconnu","autres":""},"humains":{"enfants":"non","adultes":"non","texte":"Les branches se mangent. Chez certaines personnes, le céleri donne une allergie parfois forte (bouche qui gonfle, difficulté à respirer)."},"parties":[],"substances":["Aucune substance toxique connue. Le céleri est un aliment allergisant courant."],"pourquoi":"Le céleri est un légume courant. Le seul danger bien connu est l'allergie chez certaines personnes.","symptomes":["Bouche qui picote ou gonfle (allergie)","Mal de ventre si un animal en mange beaucoup"],"que_faire":["Si quelqu'un a mange beaucoup de cette plante et se sent mal, rincer la bouche et boire un peu d'eau.","En cas de doute ou de signes qui durent : appeler un centre antipoison (numéro de votre région) ou le 15. Si la personne va mal : 15 ou 112.","Pour un animal malade : appeler un vétérinaire.","Garder un morceau de la plante ou une photo."],"precautions":["Une personne allergique au céleri doit l'éviter.","Laver les branches avant de les manger."],"precision":"Pas de toxicité connue mais non confirmée : par prudence, ne pas la laisser manger. L'allergie au céleri est connue, mais n'a pas été confirmée par une source ouverte ici.","verifie":false,"sources":[{"titre":"ASPCA - Liste des plantes toxiques pour les chiens","url":"https://www.aspca.org/pet-care/animal-poison-control/dogs-plant-list"},{"titre":"ASPCA - Liste des plantes toxiques pour les chats","url":"https://www.aspca.org/pet-care/animal-poison-control/cats-plant-list"}]},
 "fenouil": {"niveau":"aucune","resume":"Sans danger pour les chats, les chiens et les chevaux selon l'ASPCA. Se mange en légume.","animaux":{"chats":"non","chiens":"non","autres":"Non toxique pour les chevaux (ASPCA). Éviter l'huile concentrée."},"humains":{"enfants":"non","adultes":"non","texte":"Le bulbe, les feuilles et les graines se mangent comme légume ou épice."},"parties":[],"substances":["Aucune substance toxique."],"pourquoi":"Cette plante n'est pas connue pour être toxique. Son huile concentrée est à éviter.","symptomes":["Rien de spécial avec la plante."],"que_faire":["Si quelqu'un a mange beaucoup de cette plante et se sent mal, rincer la bouche et boire un peu d'eau.","En cas de doute ou de signes qui durent : appeler un centre antipoison (numéro de votre région) ou le 15. Si la personne va mal : 15 ou 112.","Pour un animal malade : appeler un vétérinaire.","Garder un morceau de la plante ou une photo."],"precautions":["Ne pas donner d'huile essentielle de fenouil aux animaux."],"precision":"L'ASPCA liste Foeniculum vulgare ; le fenouil bulbe (var. azoricum) est de la même espèce.","verifie":true,"sources":[{"titre":"ASPCA - Fenouil","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/fennel"}]}
